const SHEET_ID = "YOUR_GOOGLE_SHEET_ID";
const TELEGRAM_CHAT_ID = "YOUR_TELEGRAM_CHAT_ID";
const TANGGAL_ACUAN = "";
const TOTAL_MILESTONE      = 5;
const AMBANG_NUDGE_HARI    = 2;
const AMBANG_ESKALASI_HARI = 5;
const MAKS_NUDGE_DIABAIKAN = 3;
const JEDA_NUDGE_HARI      = 2;
const JEDA_ESKALASI_HARI   = 7;
const HARI_ANGGAP_DIABAIKAN = 1;
const AMBANG_NUDGE_TAHAP_3 = 3;
const SKOR_TINGGI = 60;
const SKOR_SEDANG = 30;
const MAKS_PANJANG_PESAN = 600;
return [{ json: {
  SHEET_ID, TELEGRAM_CHAT_ID, TANGGAL_ACUAN, TOTAL_MILESTONE,
  AMBANG_NUDGE_HARI, AMBANG_ESKALASI_HARI, MAKS_NUDGE_DIABAIKAN,
  JEDA_NUDGE_HARI, JEDA_ESKALASI_HARI, HARI_ANGGAP_DIABAIKAN,
  AMBANG_NUDGE_TAHAP_3, SKOR_TINGGI, SKOR_SEDANG, MAKS_PANJANG_PESAN
} }];

const cfg = $("Konfigurasi").first().json;
function keTanggal(nilai) {
  if (nilai === null || nilai === undefined) return null;
  const t = String(nilai).trim();
  const m = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return null;
  return new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
}
function selisihHari(dari, sampai) {
  if (!dari || !sampai) return null;
  return Math.floor((sampai.getTime() - dari.getTime()) / 86400000);
}
function terbaru(rows, jenisLog) {
  const tgl = rows
    .filter(function (r) { return String(r.jenis).trim().toLowerCase() === jenisLog; })
    .map(function (r) { return keTanggal(r.tanggal); })
    .filter(function (d) { return d !== null; })
    .sort(function (a, b) { return b.getTime() - a.getTime(); });
  return tgl.length > 0 ? tgl[0] : null;
}
const ACUAN = keTanggal(cfg.TANGGAL_ACUAN) || keTanggal(new Date().toISOString());
function bersih(rows) {
  return rows.map(function (i) { return i.json; })
    .filter(function (r) { return r && String(r.customer_id || "").indexOf("CUST-") === 0; });
}
const barisPelanggan = bersih($("Ambil Pelanggan").all());
const barisProgress  = bersih($("Ambil Progress").all());
const barisLog       = bersih($("Ambil Log Interaksi").all());
if (barisPelanggan.length === 0) {
  throw new Error("Sheet Pelanggan kosong. Cek SHEET_ID di node Konfigurasi dan nama tab.");
}
const hasil = [];
for (const p of barisPelanggan) {
  const id = String(p.customer_id).trim();
  const statusPelanggan = String(p.status_onboarding || "").trim().toLowerCase();
  const ms = barisProgress
    .filter(function (r) { return String(r.customer_id).trim() === id; })
    .sort(function (a, b) { return Number(a.milestone_id) - Number(b.milestone_id); });
  const sudahSelesai = ms.filter(function (m) { return String(m.status).trim().toLowerCase() === "selesai"; });
  const belumSelesai = ms.filter(function (m) { return String(m.status).trim().toLowerCase() !== "selesai"; });
  const jumlahSelesai   = sudahSelesai.length;
  const tahapMacet      = belumSelesai.length > 0 ? Number(belumSelesai[0].milestone_id) : 0;
  const namaTahapMacet  = belumSelesai.length > 0 ? String(belumSelesai[0].nama_milestone || "") : "";
  const catatanTahap    = belumSelesai.length > 0 ? String(belumSelesai[0].catatan || "") : "";
  let hariMacet = 0;
  for (const m of belumSelesai) { const h = Number(m.hari_di_tahap_ini) || 0; if (h > hariMacet) hariMacet = h; }
  const milestone4Selesai = ms.some(function (m) {
    return Number(m.milestone_id) === 4 && String(m.status).trim().toLowerCase() === "selesai";
  });
  const hariSejakSignupRaw = selisihHari(keTanggal(p.tanggal_signup), ACUAN);
  const hariSejakSignup = hariSejakSignupRaw === null ? 0 : hariSejakSignupRaw;
  const logPelanggan = barisLog.filter(function (r) { return String(r.customer_id).trim() === id; });
  const semuaNudge = logPelanggan.filter(function (r) { return String(r.jenis).trim().toLowerCase() === "nudge"; });
  const nudgeDiabaikan = semuaNudge.filter(function (r) {
    if (String(r.direspon).trim().toLowerCase() !== "tidak") return false;
    const umur = selisihHari(keTanggal(r.tanggal), ACUAN);
    return umur === null || umur >= cfg.HARI_ANGGAP_DIABAIKAN;
  }).length;
  const nudgeTerakhir = terbaru(logPelanggan, "nudge");
  const hariSejakNudge = nudgeTerakhir ? selisihHari(nudgeTerakhir, ACUAN) : 9999;
  const eskalasiTerakhir = terbaru(logPelanggan, "eskalasi");
  const hariSejakEskalasi = eskalasiTerakhir ? selisihHari(eskalasiTerakhir, ACUAN) : 9999;
  let skor = 0;
  const alasanSkor = [];
  if (hariSejakSignup > 7 && jumlahSelesai === 0) { skor += 40; alasanSkor.push("7+ hari tanpa satu milestone pun (+40)"); }
  if (hariMacet >= cfg.AMBANG_ESKALASI_HARI) { skor += 30; alasanSkor.push("macet " + hariMacet + " hari, sudah level eskalasi (+30)"); }
  if (nudgeDiabaikan >= 2) { skor += 20; alasanSkor.push(nudgeDiabaikan + "x nudge diabaikan (+20)"); }
  if (!milestone4Selesai && hariSejakSignup > 14) { skor += 30; alasanSkor.push("belum transaksi pertama setelah 14 hari (+30)"); }
  let levelRisiko = "RENDAH";
  if (skor >= cfg.SKOR_TINGGI) levelRisiko = "TINGGI";
  else if (skor >= cfg.SKOR_SEDANG) levelRisiko = "SEDANG";
  const ambangNudgeEfektif = tahapMacet === 3 ? cfg.AMBANG_NUDGE_TAHAP_3 : cfg.AMBANG_NUDGE_HARI;
  let aksi = "LEWATI", sebab = "";
  if (statusPelanggan !== "aktif") {
    aksi = "LEWATI"; sebab = "status onboarding sudah " + statusPelanggan + ", di luar cakupan Jalur A";
  } else if (jumlahSelesai >= cfg.TOTAL_MILESTONE) {
    aksi = "PENUTUP"; sebab = "semua " + cfg.TOTAL_MILESTONE + " milestone selesai, onboarding siap ditutup";
  } else if (nudgeDiabaikan >= cfg.MAKS_NUDGE_DIABAIKAN) {
    aksi = "STOP"; sebab = nudgeDiabaikan + "x nudge diabaikan, sistem berhenti mengirim dan menyerahkan ke manusia";
  } else if (hariMacet >= cfg.AMBANG_ESKALASI_HARI && hariSejakEskalasi >= cfg.JEDA_ESKALASI_HARI) {
    aksi = "ESKALASI"; sebab = "macet " + hariMacet + " hari di milestone " + tahapMacet + ", lewat ambang " + cfg.AMBANG_ESKALASI_HARI + " hari";
  } else if (hariMacet >= cfg.AMBANG_ESKALASI_HARI) {
    aksi = "LEWATI"; sebab = "sudah dieskalasi " + hariSejakEskalasi + " hari lalu, menunggu tindak lanjut CS";
  } else if (hariMacet >= ambangNudgeEfektif && hariSejakNudge >= cfg.JEDA_NUDGE_HARI) {
    aksi = "NUDGE"; sebab = "macet " + hariMacet + " hari di milestone " + tahapMacet;
  } else if (hariMacet >= ambangNudgeEfektif) {
    aksi = "LEWATI"; sebab = "masih dalam jeda anti-spam, terakhir dinudge " + hariSejakNudge + " hari lalu";
  } else if (tahapMacet === 3 && hariMacet >= cfg.AMBANG_NUDGE_HARI) {
    aksi = "LEWATI"; sebab = "masih masa tenggang verifikasi QRIS (" + hariMacet + " dari " + cfg.AMBANG_NUDGE_TAHAP_3 + " hari)";
  } else {
    aksi = "LEWATI"; sebab = "progres lancar, tidak perlu diganggu";
  }
  hasil.push({ json: {
    customer_id: id, nama_bisnis: p.nama_bisnis, no_wa: String(p.no_wa || ""),
    paket: p.paket, status_onboarding: statusPelanggan, aksi, sebab,
    tahap_macet: tahapMacet, nama_tahap_macet: namaTahapMacet, catatan_tahap: catatanTahap,
    hari_macet: hariMacet, ambang_nudge_efektif: ambangNudgeEfektif,
    jumlah_milestone_selesai: jumlahSelesai, milestone4_selesai: milestone4Selesai,
    hari_sejak_signup: hariSejakSignup, nudge_diabaikan: nudgeDiabaikan,
    hari_sejak_nudge_terakhir: hariSejakNudge, hari_sejak_eskalasi_terakhir: hariSejakEskalasi,
    skor_risiko_churn: skor, level_risiko: levelRisiko, alasan_skor: alasanSkor.join("; "),
    tanggal_acuan: cfg.TANGGAL_ACUAN || "hari ini"
  } });
}
return hasil;

const cfg = $("Konfigurasi").first().json;
const ACUAN = String(cfg.TANGGAL_ACUAN || new Date().toISOString().slice(0, 10));
const PANDUAN = {
  1: "Buka Pengaturan lalu Profil Outlet. Isi nama outlet, alamat, nomor telepon aktif, dan jam operasional. Langsung aktif tanpa menunggu verifikasi. Perkiraan 5-10 menit.",
  2: "Buka Menu lalu Tambah Item. Butuh minimal 5 item aktif. Kalau item lebih dari 20, pakai fitur Import dari Excel dengan template resmi. Perkiraan 20-60 menit.",
  3: "Buka Pengaturan, Pembayaran, lalu QRIS. Siapkan foto KTP pemilik usaha yang jelas dan tidak terpotong, serta data rekening. Verifikasi memakan 1 hari kerja. Sambil menunggu, Tunai dan Transfer Bank sudah bisa dipakai tanpa verifikasi.",
  4: "Buka Kasir, pilih item, lalu tap Bayar. Cukup transaksi percobaan senilai Rp 1.000 untuk memastikan menu, pembayaran, dan struk berjalan. Perkiraan 5 menit. Ini langkah paling menentukan.",
  5: "Buka Pengaturan, Tim, lalu Undang Anggota. Masukkan nomor WhatsApp staff dan pilih role Kasir, Supervisor, atau Manager. Perkiraan 5 menit."
};
const keluaran = [];
for (const item of $input.all()) {
  const d = item.json;
  const isPenutup = d.aksi === "PENUTUP";
  const panduanTahap = PANDUAN[d.tahap_macet] || "";
  let prompt, pesanCadangan;
  if (isPenutup) {
    prompt = [
      "Situasi: pelanggan BARU SAJA menyelesaikan seluruh " + cfg.TOTAL_MILESTONE + " milestone onboarding.",
      "Nama outlet: " + d.nama_bisnis, "Paket langganan: " + d.paket,
      "Lama proses: " + d.hari_sejak_signup + " hari sejak daftar.", "",
      "Tugas: tulis satu pesan penutup onboarding. Ucapkan selamat, sebut singkat bahwa outlet sudah siap beroperasi penuh, dan beri tahu bahwa mereka bisa membalas pesan ini kapan saja kalau butuh bantuan."
    ].join("\n");
    pesanCadangan = "Halo Kak, selamat! Seluruh " + cfg.TOTAL_MILESTONE +
      " langkah onboarding " + d.nama_bisnis + " sudah selesai. Outlet Kakak siap beroperasi penuh. Kalau nanti ada yang mau ditanyakan, balas pesan ini saja ya.";
  } else {
    prompt = [
      "Situasi: pelanggan tersendat di satu langkah onboarding.",
      "Nama outlet: " + d.nama_bisnis, "Paket langganan: " + d.paket,
      "Progres: " + d.jumlah_milestone_selesai + " dari " + cfg.TOTAL_MILESTONE + " milestone selesai.",
      "Langkah yang tersendat: milestone " + d.tahap_macet + " - " + d.nama_tahap_macet,
      "Sudah tersendat: " + d.hari_macet + " hari.",
      "Catatan sistem: " + (d.catatan_tahap || "tidak ada"),
      "Riwayat: sudah " + d.nudge_diabaikan + " kali dikirimi pesan tanpa balasan.", "",
      "Panduan resmi untuk langkah ini (SATU-SATUNYA sumber fakta yang boleh kamu pakai):",
      panduanTahap, "",
      "Tugas: tulis satu pesan WhatsApp singkat untuk membantu pelanggan melewati langkah ini."
    ].join("\n");
    pesanCadangan = "Halo Kak, kami lihat langkah \"" + d.nama_tahap_macet +
      "\" di " + d.nama_bisnis + " belum selesai. Ada kendala yang bisa kami bantu? Balas pesan ini saja ya.";
  }
  keluaran.push({ json: {
    customer_id: d.customer_id, nama_bisnis: d.nama_bisnis, no_wa: d.no_wa,
    paket: d.paket, aksi: d.aksi, tahap_macet: d.tahap_macet,
    nama_tahap_macet: d.nama_tahap_macet, catatan_tahap: d.catatan_tahap,
    hari_macet: d.hari_macet, jumlah_milestone_selesai: d.jumlah_milestone_selesai,
    hari_sejak_signup: d.hari_sejak_signup, nudge_diabaikan: d.nudge_diabaikan,
    skor_risiko_churn: d.skor_risiko_churn, level_risiko: d.level_risiko,
    sebab: d.sebab, prompt_pengguna: prompt, pesan_cadangan: pesanCadangan,
    log_id: "LOG-" + ACUAN.replace(/-/g, "") + "-" + String(d.customer_id).replace("CUST-", "") + (isPenutup ? "-P" : "-N"),
    log_tanggal: ACUAN, log_jenis: isPenutup ? "penutup" : "nudge",
    log_direspon: isPenutup ? "-" : "tidak",
    log_tindak_lanjut: isPenutup ? "Onboarding ditutup" : "Menunggu respons pelanggan"
  } });
}
return keluaran;

const cfg = $("Konfigurasi").first().json;
const asal = $("Susun Prompt Pesan").item.json;
let teks = String($json.text || $json.output || "").trim();
teks = teks.replace(/^[\s"'`]+/, "").replace(/[\s"'`]+$/, "").trim();
teks = teks.replace(/^(Pesan|Jawaban|Output|Balasan)\s*:\s*/i, "").trim();
const masalah = [];
if (teks.length === 0) masalah.push("keluaran AI kosong");
if (teks.length > cfg.MAKS_PANJANG_PESAN) masalah.push("terlalu panjang (" + teks.length + " karakter)");
if (/\b(gratis|diskon|promo|refund|garansi|dijamin|pasti)\b/i.test(teks)) masalah.push("mengandung janji komersial");
if (/Rp\s?[\d.,]{4,}/i.test(teks) && asal.tahap_macet !== 4) masalah.push("menyebut nominal di luar konteks");
let sumber = "ai";
if (masalah.length > 0) { teks = asal.pesan_cadangan; sumber = "cadangan"; }
return { json: Object.assign({}, asal, {
  pesan_pelanggan: teks, sumber_pesan: sumber,
  masalah_pesan: masalah.join("; "), panjang_pesan: teks.length,
  log_isi: (asal.aksi === "PENUTUP" ? "PENUTUP - " : "NUDGE ms" + asal.tahap_macet + " - ") + teks.slice(0, 120)
}) };

const cfg = $("Konfigurasi").first().json;
const ACUAN = String(cfg.TANGGAL_ACUAN || new Date().toISOString().slice(0, 10));
function amanHtml(teks) {
  return String(teks === null || teks === undefined ? "" : teks)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
const keluaran = [];
for (const item of $input.all()) {
  const d = item.json;
  const isStop = d.aksi === "STOP";
  const judul = isStop ? "SISTEM BERHENTI - SERAHKAN KE MANUSIA" : "ESKALASI KE CS";
  const tanda = d.level_risiko === "TINGGI" ? "MERAH" : (d.level_risiko === "SEDANG" ? "ORANYE" : "KUNING");
  const baris = [];
  baris.push("<b>" + amanHtml(judul) + "</b>");
  baris.push("Prioritas: " + tanda + " | Risiko churn " + d.skor_risiko_churn + " (" + d.level_risiko + ")");
  baris.push("");
  baris.push("Outlet: " + amanHtml(d.nama_bisnis) + " (" + d.customer_id + ")");
  baris.push("Paket: " + amanHtml(d.paket) + " | WA: " + amanHtml(d.no_wa));
  baris.push("Umur akun: " + d.hari_sejak_signup + " hari");
  baris.push("");
  baris.push("Tersendat di milestone " + d.tahap_macet + " - " + amanHtml(d.nama_tahap_macet));
  baris.push("Lama tersendat: " + d.hari_macet + " hari");
  baris.push("Progres: " + d.jumlah_milestone_selesai + "/" + cfg.TOTAL_MILESTONE + " milestone selesai");
  baris.push("Nudge diabaikan: " + d.nudge_diabaikan + "x");
  baris.push("Catatan tahap: " + amanHtml(d.catatan_tahap || "-"));
  baris.push("");
  baris.push("Faktor risiko: " + amanHtml(d.alasan_skor || "-"));
  baris.push("Alasan sistem: " + amanHtml(d.sebab));
  baris.push("");
  baris.push(isStop
    ? "Tindakan: sistem TIDAK akan mengirim pesan otomatis lagi ke pelanggan ini. Butuh kontak manual."
    : "Tindakan: hubungi pelanggan secara manual. Sistem tetap memantau.");
  baris.push("Tanggal acuan: " + ACUAN);
  const ringkasSingkat = (isStop ? "STOP - " : "ESKALASI - ") +
    "macet " + d.hari_macet + " hari di milestone " + d.tahap_macet +
    ", skor churn " + d.skor_risiko_churn + " (" + d.level_risiko + ")";
  keluaran.push({ json: {
    customer_id: d.customer_id, nama_bisnis: d.nama_bisnis, aksi: d.aksi,
    perlu_serahkan_cs: isStop, pesan_admin: baris.join("\n"),
    log_id: "LOG-" + ACUAN.replace(/-/g, "") + "-" + String(d.customer_id).replace("CUST-", "") + "-E",
    log_tanggal: ACUAN, log_jenis: "eskalasi", log_isi: ringkasSingkat,
    log_direspon: "-", log_tindak_lanjut: isStop ? "Diserahkan ke CS, sistem berhenti mengirim" : "CS perlu follow-up manual"
  } });
}
return keluaran;
